const item = $input.first().json;
let rawText = '';

if (item.text) {
  rawText = item.text;
} else if (item.candidates && item.candidates[0]?.content?.parts?.[0]?.text) {
  rawText = item.candidates[0].content.parts[0].text;
} else if (typeof item === 'string') {
  rawText = item;
} else {
  throw new Error('Khong tim thay noi dung phan hoi tu AI');
}

let clean = rawText.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').replace(/```/g, '').trim();
let parsed = null;

try {
  parsed = JSON.parse(clean);
} catch (e1) {
  try {
    const sanitized = clean.replace(/[\u0000-\u001F]+/g, (m) => {
      if (m === '\n') return '\\n';
      if (m === '\r') return '\\r';
      if (m === '\t') return '\\t';
      return '';
    });
    parsed = JSON.parse(sanitized);
  } catch (e2) {
    const titleMatch = clean.match(/"title"\s*:\s*"((?:\\.|[^"\\])*)"/s);
    const summaryMatch = clean.match(/"summary"\s*:\s*"((?:\\.|[^"\\])*)"/s);
    const categoryMatch = clean.match(/"category"\s*:\s*"((?:\\.|[^"\\])*)"/s);
    const tagsMatch = clean.match(/"tags"\s*:\s*"((?:\\.|[^"\\])*)"/s);

    let content = '';
    const contentRegex = /"content"\s*:\s*"([\s\S]*)/i;
    const match = clean.match(contentRegex);
    if (match) {
      let remainder = match[1];
      remainder = remainder.replace(/"\s*}\s*$/i, '');
      content = remainder.replace(/\\n/g, '\n').replace(/\\r/g, '').replace(/\\"/g, '"');
    }

    if (titleMatch || content) {
      parsed = {
        title: titleMatch ? titleMatch[1].replace(/\\"/g, '"') : 'Bai viet moi tu Tu Hoc AI',
        summary: summaryMatch ? summaryMatch[1].replace(/\\"/g, '"') : '',
        category: categoryMatch ? categoryMatch[1] : 'WORKFLOW',
        tags: tagsMatch ? tagsMatch[1] : 'n8n, Tu Dong Hoa, AI, tuhocai',
        content: content || 'Noi dung dang cap nhat'
      };
    } else {
      throw new Error('Loi parse JSON tu AI: ' + e1.message + '\nNoi dung goc:\n' + rawText);
    }
  }
}

return {
  json: {
    title: parsed.title,
    summary: parsed.summary,
    content: parsed.content,
    category: parsed.category || 'WORKFLOW',
    tags: parsed.tags || 'n8n, Tu Dong Hoa, AI, tuhocai',
    isFeatured: true,
    isPublished: true
  }
};

